function fields=innerloop_output_fields(include_signal)
% Append-only interface: original outputs 1..15 retain their meaning/number.
if nargin<1, include_signal=false; end
fields={'T_world_deck','T_deck_camera','velocity_deck', ...
    'helicopter_velocity_ned_mps','ship_velocity_ned_mps', ...
    'gear_relative_truth_ned','gear_relative_estimate_ned', ...
    'relative_distance_estimate_m','relative_covariance_ned','feedback_valid', ...
    'navigation_velocity_camera_ned_mps','state_timestamp','T_body_camera_actual', ...
    'nav_T_deck_body','navigation_velocity_gear_ned_mps', ...
    'cg_relative_truth_ned','cg_relative_estimate_ned', ...
    'navigation_velocity_cg_ned_mps','cg_relative_covariance_ned'};
if include_signal
    fields=[fields {'cg_relative_estimate_50hz_ned','cg_relative_velocity_50hz_ned_mps', ...
        'cg_signal_valid','cg_signal_age_s'}];
end
end
